import Foundation
import Testing
@testable import DesignTokens

@Suite("Emitters")
struct EmitterTests {
    @Test("CSS declares light values on :root and dark values under both dark selectors")
    func cssStructure() {
        let css = CSSEmitter.emit()
        #expect(css.hasPrefix("/* Generated by design-tokens. Do not edit."))
        #expect(css.contains(":root {"))
        #expect(css.contains("--accent: #FF8D28;"))
        #expect(css.contains("@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {"))
        #expect(css.contains(":root[data-theme=\"dark\"] {"))
        #expect(css.contains("--accent: #FF9230;"))
        #expect(css.contains("--series-8: #00C0E8;"))
        #expect(css.contains("--rule-hairline: 1px;"))
        #expect(css.contains("--gutter: 16px;"))
    }

    @Test("an unmeasured dark value is not emitted, so the light value carries through")
    func cssSkipsUnmeasured() {
        let dark = CSSEmitter.emit().components(separatedBy: "@media (prefers-color-scheme: dark)")[1]
        #expect(!dark.contains("--success:"))
    }

    @Test("JSON is valid, sorted and carries the snapshot release")
    func jsonStructure() throws {
        let data = Data(JSONEmitter.emit().utf8)
        let object = try #require(JSONSerialization.jsonObject(with: data) as? [String: Any])
        #expect(object["systemRelease"] as? String == "macOS 27.2")
        let colors = try #require(object["colors"] as? [String: [String: String]])
        #expect(colors["accent"]?["light"] == "#FF8D28")
        #expect(colors["success"]?["dark"] == nil)
    }

    @Test("checked-in generated files equal a fresh emit")
    func goldenFiles() throws {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        let css = try String(contentsOf: root.appendingPathComponent("Generated/tokens.css"), encoding: .utf8)
        let json = try String(contentsOf: root.appendingPathComponent("Generated/tokens.json"), encoding: .utf8)
        #expect(css == CSSEmitter.emit())
        #expect(json == JSONEmitter.emit())
    }
}
